// ১. এআই-এর পাঠানো টেক্সট ইনপুট নেওয়া হচ্ছে
let aiOutput = $input.item.json.query;

if (!aiOutput) {
    return "কোনো তারিখ বা সময় পাওয়া যায়নি। অনুগ্রহ করে সঠিক সময়টি বলুন।";
}

// ২. টেক্সট থেকে কমা (,) এবং 'at' শব্দগুলো পরিষ্কার করা হচ্ছে যেন জাভাস্ক্রিপ্ট সহজে বুঝতে পারে
// এটি "Sunday, June 14, 2026, at 10:00 PM" কে "June 14, 2026 10:00 PM" এ রূপান্তর করবে
let cleanDateText = aiOutput.replace(/at/g, '').replace(/,/g, '').trim();

// ৩. ডেট অবজেক্টে রূপান্তর করার চেষ্টা
const parsedDate = new Date(cleanDateText);

// ৪. ভ্যালিডেশন চেক: যদি তারিখটি সঠিক (Valid) হয়
if (!isNaN(parsedDate.getTime())) {
    const startTime = parsedDate.toISOString();
    const endTime = new Date(parsedDate.getTime() + 60 * 60 * 1000).toISOString(); // ১ ঘণ্টা যোগ করা হলো

    return `SUCCESS: ISO Start Time is ${startTime} and End Time is ${endTime}`;
} else {
    // ৫. একদম শেষ ব্যাকআপ প্ল্যান (যদি কোনোভাবেই রিড না করা যায়)
    const backupDate = new Date();
    backupDate.setHours(backupDate.getHours() + 1);

    const startTime = backupDate.toISOString();
    const endTime = new Date(backupDate.getTime() + 60 * 60 * 1000).toISOString();

    return `SUCCESS: Input text processed with backup. Start Time: ${startTime}, End Time: ${endTime}`;
}

