    },
    "email_body": {
      "type": "string",
      "description": "The complete body text of the email, starting from the greeting (e.g., 'Dear...') all the way to the sign-off."
    },
    "threadId": {
      "type": "string",
      "description": "The unique thread ID if available, otherwise return an empty string or null.",
      "default": ""
    }
  },
  "required": ["subject_line", "email_body"]
}

parameters.jsCode:
const event = $input.item.json;
const startTime = new Date(event.start.dateTime);
const now = new Date();
const diffMinutes = Math.floor((startTime - now) / 1000 / 60);

// Only send reminder if exactly 30 minutes before (within 1-minute window)
if (diffMinutes >= 29 && diffMinutes <= 30) {
  const timeStr = startTime.toLocaleTimeString('en-US', { 
    hour: '2-digit', 
    minute: '2-digit',
    hour12: true 
  });

  let message = '⏰ *Meeting Reminder*\n\n';
  message += `Your meeting "${event.summary || 'Untitled Event'}" starts in 30 minutes!\n\n`;
  message += `🕐 Time: ${timeStr}\n`;

  if (event.description) {
    message += `📝 ${event.description}`;
  }

  return { json: { shouldSend: true, message } };
}

return { json: { shouldSend: false } };
